deepml vfx 0.3
module corpus.deepml_vfx.example_04001
policy deterministic
policy no_network
effect Effect04001 {
  coupled simulation PortalSim seed 4001 { fluid: Energy cloth: Veil particles: Sparks }
  procedural operator Distort(time, portal_state) differentiable
  cache PortalCache8 interval 0s..10s step 1/60s hash sha256("cache:04001")
  bind scene PortalScene6
  bind timeline PortalSequence10
  render_graph { Sim -> Lighting -> Distortion -> Composite }
  composite multipass [SceneColor, PortalGlow, Distortion, Atmosphere]
}

